{
  "contract": "QuantumEnergy",
  "closure": {
    "site_function": "sendFee",
    "site_call": ".balanceOf",
    "functions": [
      "claimReward",
      "getReward",
      "transfer",
      "transferFrom"
    ],
    "justification": "These functions interact with the exposed storage variables LiqQueue and feeQueue."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "claimReward",
      "getReward",
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "claimReward": 1,
      "getReward": 1,
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "sendFee",
    "pre": {
      "name": "pre",
      "from_marker": "start_pre",
      "to_marker": "end_pre"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "start_exposed",
      "to_marker": "end_exposed"
    },
    "post": {
      "name": "post",
      "from_marker": "start_post",
      "to_marker": "end_post"
    },
    "linearization_point": "end_exposed"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of assets in transit during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "feeQueue + LiqQueue == snapPre + inFlight",
    "stable_formula": "feeQueue + LiqQueue == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "feeQueue + LiqQueue <= balanceOf[address(this)]",
    "rule": "The exposure invariant ensures that the sum of feeQueue and LiqQueue is conserved across the callback window, allowing the target property to hold."
  }
}
